<?php
declare(strict_types=1);
session_name('openhost_session');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off'),'httponly'=>true,'samesite'=>'Strict']);
session_start();
const DATA_DIR='/opt/openhost-panel/data';
const USER_FILE=DATA_DIR.'/admin.json';
const TOKEN_FILE='/etc/openhost-panel/agent.token';
function e(string $value): string { return htmlspecialchars($value, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function loadUser(): array { $data=json_decode((string)@file_get_contents(USER_FILE),true); return is_array($data)?$data:['username'=>'admin','hash'=>'','must_change'=>true]; }
function saveUser(array $user): void { $tmp=USER_FILE.'.tmp'; if(file_put_contents($tmp,json_encode($user,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX)===false) throw new RuntimeException('Tidak dapat menyimpan akun.'); chmod($tmp,0600); if(!rename($tmp,USER_FILE)) throw new RuntimeException('Tidak dapat memperbarui akun.'); }
function agentRequest(string $method,string $path,array $payload=[]): array {
  $token=trim((string)@file_get_contents(TOKEN_FILE)); if($token==='') return ['ok'=>false,'error'=>'Token agent tidak dapat dibaca.'];
  $headers="Authorization: Bearer {$token}\r\n"; $content='';
  if($method==='POST') { $content=json_encode($payload,JSON_UNESCAPED_SLASHES); $headers.="Content-Type: application/json\r\n"; }
  $context=stream_context_create(['http'=>['method'=>$method,'timeout'=>15,'ignore_errors'=>true,'header'=>$headers,'content'=>$content]]);
  $body=@file_get_contents('http://127.0.0.1:8787'.$path,false,$context); $data=json_decode((string)$body,true);
  return is_array($data)?$data:['ok'=>false,'error'=>'Agent offline atau memberi respons tidak valid.'];
}
function validDomain(string $domain): bool { return strlen($domain)<=253 && (bool)preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))+$/',strtolower($domain)); }

$user=loadUser(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
  if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))) { http_response_code(400); $error='Sesi keamanan tidak valid. Muat ulang halaman.'; }
  elseif(isset($_POST['login'])) {
    $candidate=loadUser(); $username=trim((string)($_POST['username']??'')); $password=(string)($_POST['password']??'');
    if($candidate['hash']!=='' && hash_equals((string)$candidate['username'],$username) && password_verify($password,(string)$candidate['hash'])) { session_regenerate_id(true); $_SESSION['user']=$candidate['username']; header('Location: /'); exit; }
    usleep(250000); $error='Username atau password salah.';
  } elseif(isset($_POST['change_password']) && !empty($_SESSION['user'])) {
    $candidate=loadUser(); $new=(string)($_POST['new_password']??''); $confirm=(string)($_POST['confirm_password']??'');
    if(strlen($new)<12) $error='Password baru minimal 12 karakter.';
    elseif($new!==$confirm) $error='Konfirmasi password tidak sama.';
    else { $candidate['hash']=password_hash($new,PASSWORD_DEFAULT); $candidate['must_change']=false; try { saveUser($candidate); session_regenerate_id(true); $_SESSION['csrf']=bin2hex(random_bytes(32)); header('Location: /'); exit; } catch(Throwable $t) { $error=$t->getMessage(); } }
  } elseif(isset($_POST['site_create']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??'')));
    if(!validDomain($domain)) $error='Format domain tidak valid. Contoh: example.com';
    else { $result=agentRequest('POST','/api/v1/sites/create',['domain'=>$domain]); if(!empty($result['ok'])) { $_SESSION['flash']='Website '.$domain.' berhasil dibuat.'; header('Location: /?page=websites'); exit; } $error=(string)($result['error']??'Gagal membuat website.'); }
  } elseif(isset($_POST['site_disable']) && !empty($_SESSION['user']) && empty($user['must_change'])) {
    $domain=strtolower(trim((string)($_POST['domain']??'')));
    if(!validDomain($domain)) $error='Format domain tidak valid.';
    else { $result=agentRequest('POST','/api/v1/sites/disable',['domain'=>$domain]); if(!empty($result['ok'])) { $_SESSION['flash']='Website '.$domain.' dinonaktifkan. File tetap disimpan.'; header('Location: /?page=websites'); exit; } $error=(string)($result['error']??'Gagal menonaktifkan website.'); }
  } elseif(isset($_POST['logout'])) { $_SESSION=[]; session_regenerate_id(true); header('Location: /'); exit; }
}
$logged=!empty($_SESSION['user']); $user=loadUser(); $page=(string)($_GET['page']??'dashboard');
$metrics=agentRequest('GET','/api/v1/metrics');
