.navlabel,.nav a span,.sidefoot{display:none}.nav a{justify-content:center;padding:13px 4px}.main{padding:22px 14px}.top{align-items:flex-start;flex-direction:column}.grid{gap:10px}.card{padding:15px}.value{font-size:24px}.formgrid{grid-template-columns:1fr}}
